def.body:
if @frozen
  return
end

@commands_3d.each(&.step(delta))
@commands_2d.each(&.step(delta))
@text_3d.each(&.step(delta))
@text_2d.each(&.step(delta))


@commands_3d.reject! do |c| c.duration <= 0.0 || c.expired? end
@commands_2d.reject! do |c| c.duration <= 0.0 || c.expired? end
@text_3d.reject! do |c| c.duration <= 0.0 || c.expired? end
@text_2d.reject! do |c| c.duration <= 0.0 || c.expired? end

val = value.to_f32
if @samples.size >= max_samples
  @samples.shift
end
@samples << val
